class _Replay(Lexer):
    """
    Yield tokens the lexer Lark already produced. This parser does not
    lex.
    """

    pending: list = []

    def __init__(self, lexer_conf: object) -&gt; None:
        pass

    def lex(self, lexer_state: object, parser_state: object = None) -&gt; object:
        yield from _Replay.pending


